CREATE PROCEDURE wf_install_northshire_chain()
main: BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  IF EXISTS (SELECT 1 FROM wowforever_content_ports WHERE name='northshire-chain-335-v1') THEN
    COMMIT;
    SELECT 'Already installed; no changes' AS result;
    LEAVE main;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=7)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=15)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=21)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=54)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=783)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=21 AND `RewardChoiceItemID1`=2186)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=21 AND `RewardChoiceItemID2`=2691)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=21 AND `RewardChoiceItemID3`=11192)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=54 AND `StartItem`=745)
     OR NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=54 AND `RewardItem1`=6078)
     OR NOT EXISTS (SELECT 1 FROM creature_template WHERE entry=197)
     OR NOT EXISTS (SELECT 1 FROM creature_template_model WHERE CreatureID=197)
     OR NOT EXISTS (SELECT 1 FROM creature_template_difficulty WHERE Entry=197)
     OR NOT EXISTS (SELECT 1 FROM creature WHERE id=197 AND map=0)
     OR NOT EXISTS (SELECT 1 FROM creature_template WHERE entry=240)
     OR NOT EXISTS (SELECT 1 FROM creature_template_model WHERE CreatureID=240)
     OR NOT EXISTS (SELECT 1 FROM creature_template_difficulty WHERE Entry=240)
     OR NOT EXISTS (SELECT 1 FROM creature WHERE id=240 AND map=0)
     OR NOT EXISTS (SELECT 1 FROM creature_template WHERE entry=823)
     OR NOT EXISTS (SELECT 1 FROM creature_template_model WHERE CreatureID=823)
     OR NOT EXISTS (SELECT 1 FROM creature_template_difficulty WHERE Entry=823)
     OR NOT EXISTS (SELECT 1 FROM creature WHERE id=823 AND map=0)
     OR NOT EXISTS (SELECT 1 FROM creature_template WHERE entry=80)
     OR NOT EXISTS (SELECT 1 FROM creature WHERE id=80 AND map=0)
     OR NOT EXISTS (SELECT 1 FROM creature_template WHERE entry=257)
     OR NOT EXISTS (SELECT 1 FROM creature WHERE id=257 AND map=0)
     OR NOT EXISTS (SELECT 1 FROM creature_template WHERE entry=6)
     OR NOT EXISTS (SELECT 1 FROM creature WHERE id=6 AND map=0) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing Northshire prerequisites; no content installed';
  END IF;
  IF EXISTS (SELECT 1 FROM `quest_template` WHERE `ID` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `quest_template_addon` WHERE `ID` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `quest_classic_level` WHERE `ID` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `quest_classic_money` WHERE `ID` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `quest_template_classic_level` WHERE `ID` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `quest_request_items` WHERE `ID` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `quest_objectives` WHERE `QuestID` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `creature_template` WHERE `entry` IN (910197,910240,910823))
     OR EXISTS (SELECT 1 FROM `creature_template_model` WHERE `CreatureID` IN (910197,910240,910823))
     OR EXISTS (SELECT 1 FROM `creature_template_difficulty` WHERE `Entry` IN (910197,910240,910823))
     OR EXISTS (SELECT 1 FROM `creature` WHERE `guid` IN (910000001,910000002,910000003))
     OR EXISTS (SELECT 1 FROM `creature` WHERE `id` IN (910197,910240,910823))
     OR EXISTS (SELECT 1 FROM `creature_queststarter` WHERE `id` IN (910197,910240,910823))
     OR EXISTS (SELECT 1 FROM `creature_queststarter` WHERE `quest` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `creature_questender` WHERE `id` IN (910197,910240,910823))
     OR EXISTS (SELECT 1 FROM `creature_questender` WHERE `quest` IN (910007,910015,910021,910054,910783))
     OR EXISTS (SELECT 1 FROM `quest_objectives` WHERE `ID` IN (9100070,9100150,9100210,9100544,9107830)) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved chain IDs occupied; no content installed';
  END IF;
  CREATE TEMPORARY TABLE wf_chain_copy LIKE `quest_template`;
  INSERT INTO wf_chain_copy SELECT * FROM `quest_template` WHERE `ID`=7;
  UPDATE wf_chain_copy SET `ID`=910007,`QuestType`=2,`QuestSortID`=9,`QuestInfoID`=0,`SuggestedGroupNum`=0,`RewardXPDifficulty`=5,`RewardBonusMoney`=90,`RewardSpell`=0,`RewardHonor`=0,`RewardKillHonor`=0.0,`StartItem`=0,`Flags`=8,`RewardFactionFlags`=1,`AllowableRaces`=1101,`TimeAllowed`=0,`LogTitle`='[335 chain] Kobold Camp Cleanup',`LogDescription`='Kill 8 Kobold Vermin, then return to Marshal McBride.',`QuestDescription`='Your first task is one of cleansing, $N.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.',`AreaDescription`='',`QuestCompletionLog`='Return to Marshal McBride at Northshire Abbey in Elwynn Forest.',`RewardItem1`=0,`RewardAmount1`=0,`ItemDrop1`=0,`ItemDropQuantity1`=0,`RewardItem2`=0,`RewardAmount2`=0,`ItemDrop2`=0,`ItemDropQuantity2`=0,`RewardItem3`=0,`RewardAmount3`=0,`ItemDrop3`=0,`ItemDropQuantity3`=0,`RewardItem4`=0,`RewardAmount4`=0,`ItemDrop4`=0,`ItemDropQuantity4`=0,`RewardChoiceItemID1`=0,`RewardChoiceItemQuantity1`=0,`RewardChoiceItemID2`=0,`RewardChoiceItemQuantity2`=0,`RewardChoiceItemID3`=0,`RewardChoiceItemQuantity3`=0,`RewardChoiceItemID4`=0,`RewardChoiceItemQuantity4`=0,`RewardChoiceItemID5`=0,`RewardChoiceItemQuantity5`=0,`RewardChoiceItemID6`=0,`RewardChoiceItemQuantity6`=0,`RewardFactionID1`=72,`RewardFactionValue1`=5,`RewardFactionOverride1`=0,`RewardFactionID2`=0,`RewardFactionValue2`=0,`RewardFactionOverride2`=0,`RewardFactionID3`=0,`RewardFactionValue3`=0,`RewardFactionOverride3`=0,`RewardFactionID4`=0,`RewardFactionValue4`=0,`RewardFactionOverride4`=0,`RewardFactionID5`=0,`RewardFactionValue5`=0,`RewardFactionOverride5`=0,`RewardNextQuest`=0,`VerifiedBuild`=0;
