  UPDATE wf_chain_copy SET `ID`=910783,`QuestType`=2,`QuestSortID`=9,`QuestInfoID`=0,`SuggestedGroupNum`=0,`RewardXPDifficulty`=3,`RewardBonusMoney`=30,`RewardSpell`=0,`RewardHonor`=0,`RewardKillHonor`=0.0,`StartItem`=0,`Flags`=8,`RewardFactionFlags`=1,`AllowableRaces`=1101,`TimeAllowed`=0,`LogTitle`='[335 chain] A Threat Within',`LogDescription`='Speak with Marshal McBride.',`QuestDescription`='I hope you strapped your belt on tight, young $c, because there is work to do here in Northshire.$B$BAnd I don''t mean farming.$B$BThe Stormwind guards are hard pressed to keep the peace here, with so many of us in distant lands and so many threats pressing close.  And so we''re enlisting the aid of anyone willing to defend their home.  And their alliance.$B$BIf you''re here to answer the call, then speak with my superior, Marshal McBride.  He''s inside the abbey behind me.',`AreaDescription`='',`QuestCompletionLog`=NULL,`RewardItem1`=0,`RewardAmount1`=0,`ItemDrop1`=0,`ItemDropQuantity1`=0,`RewardItem2`=0,`RewardAmount2`=0,`ItemDrop2`=0,`ItemDropQuantity2`=0,`RewardItem3`=0,`RewardAmount3`=0,`ItemDrop3`=0,`ItemDropQuantity3`=0,`RewardItem4`=0,`RewardAmount4`=0,`ItemDrop4`=0,`ItemDropQuantity4`=0,`RewardChoiceItemID1`=0,`RewardChoiceItemQuantity1`=0,`RewardChoiceItemID2`=0,`RewardChoiceItemQuantity2`=0,`RewardChoiceItemID3`=0,`RewardChoiceItemQuantity3`=0,`RewardChoiceItemID4`=0,`RewardChoiceItemQuantity4`=0,`RewardChoiceItemID5`=0,`RewardChoiceItemQuantity5`=0,`RewardChoiceItemID6`=0,`RewardChoiceItemQuantity6`=0,`RewardFactionID1`=72,`RewardFactionValue1`=3,`RewardFactionOverride1`=0,`RewardFactionID2`=0,`RewardFactionValue2`=0,`RewardFactionOverride2`=0,`RewardFactionID3`=0,`RewardFactionValue3`=0,`RewardFactionOverride3`=0,`RewardFactionID4`=0,`RewardFactionValue4`=0,`RewardFactionOverride4`=0,`RewardFactionID5`=0,`RewardFactionValue5`=0,`RewardFactionOverride5`=0,`RewardNextQuest`=910007,`VerifiedBuild`=0;
