  INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`RewardText`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`VerifiedBuild`) VALUES (910007,1,0,0,0,'Well done, citizen. Those kobolds are thieves and cowards, but in large numbers they pose a threat to us. And the humans of Stormwind do not need another threat.$B$BFor defeating them, you have my gratitude.',0,0,0,0,0);
  INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`RewardText`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`VerifiedBuild`) VALUES (910015,1,0,0,0,'I don''t like hearing of all these kobolds in our mine. No good can come of this. Here, take this as payment, and when you''re ready, speak to me again. I would like you to go back to the mines one more time...',0,0,0,0,0);
  INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`RewardText`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`VerifiedBuild`) VALUES (910021,1,0,0,0,'Once again, you have earned my respect, and the gratitude of the Stormwind Army. There may yet be kobolds in the mine, but I will marshal others against them. We have further tasks for you.',0,0,0,0,0);
  INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`RewardText`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`VerifiedBuild`) VALUES (910054,1,66,0,0,'Well, it says here that you''ve been awarded Acting Deputy Status with the Stormwind Marshals. Congratulations.$b$bAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!$b$bIt''s hard to keep track of politics in these dark days...',0,0,0,0,0);
  INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`RewardText`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`VerifiedBuild`) VALUES (910783,1,0,0,0,'Ah, good.  Another volunteer.  We''re getting a lot of you these days.$B$BI hope it''s enough.$B$BThe human lands are threatened from without, and so many of our forces have been marshaled abroad.  This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.$B$BIt is a many-fronted battle we wage, $N.  Gird yourself for a long campaign.',0,0,0,0,0);
  INSERT INTO `quest_request_items` (`ID`,`VerifiedBuild`,`CompletionText`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`) VALUES (910007,0,'How goes the hunting, $N? Have you found and defeated those vermin?',1,6,0,0);
  INSERT INTO `quest_request_items` (`ID`,`VerifiedBuild`,`CompletionText`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`) VALUES (910015,0,'Have you been to the mines? Are you ready to report?',1,6,0,0);
